///
/// Preview of the rendered SQL:
/// ```sql
/// LEFT JOIN _ParentToChild AS <alias>_m2m ON (<alias>_m2m.ParentId = <previous>.id)
/// LEFT JOIN Child AS <alias> ON (<alias>.id = <alias>_m2m.ChildId)
/// ```
pub(crate) fn compute_m2m_join(
    rf: &RelationFieldRef,
    alias: &str,
    parent_alias: Option<&str>,
    ctx: &Context<'_>,
) -> Vec<AliasedJoin> {
    let m2m_alias = format!("{alias}_m2m");
    let child_alias = alias.to_owned();

    // m2m join table (e.g. _ParentToChild)
    let m2m_table = rf.as_table(ctx).alias(m2m_alias.clone());
    // Related (child) model table
    let child_table = rf.related_model().as_table(ctx).alias(child_alias.clone());

    // Columns on the m2m table referencing the parent (the model the relation field lives on).
    let m2m_parent_columns = rf.related_field().m2m_columns(ctx);
    // Columns on the m2m table referencing the child (the related model).
    let m2m_child_columns = rf.m2m_columns(ctx);

    // Parent primary identifier columns, tabled on the previous join (or parent) alias.
    let parent_id_columns = ModelProjection::from(rf.model().primary_identifier())
        .as_columns(ctx)
        .map(|c| c.opt_table(parent_alias.map(ToOwned::to_owned)));
    // Child primary identifier columns, tabled on the child alias.
    let child_id_columns = ModelProjection::from(rf.related_model().primary_identifier())
        .as_columns(ctx)
        .map(|c| c.table(child_alias.clone()));

    // <m2m_alias>.<parent_fk> = <previous>.<parent_id>
    let parent_join_conditions: Vec<Expression> = m2m_parent_columns
        .into_iter()
        .map(|c| c.table(m2m_alias.clone()))
        .zip(parent_id_columns)
